let menu=[],activeCat=0,activeProduct=null,productSnapshot=null,pendingReviewChanges=[];
function clone(x){return JSON.parse(JSON.stringify(x))}
function obj(v=""){return{tr:v,en:v,ru:v,ar:v}}
function ensureLang(o){if(!o||typeof o!=="object")return obj(String(o||""));["tr","en","ru","ar"].forEach(l=>o[l]??="");return o}
function slug(s){return String(s||"urun").toLowerCase().normalize("NFKD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"")||"urun"}
function esc(s){return String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]))}
function setStatus(m){$("status").textContent=m}
function normalizeProduct(p,c,j){const id=p.id||`${c}-${j+1}`;return{id,name:ensureLang(p.name||obj(id)),desc:ensureLang(p.desc||obj("")),detail:ensureLang(p.detail||p.desc||obj("")),badge:ensureLang(p.badge||obj("")),price:Number(p.price)||0,image:p.image||"",localImage:(p.localImage!==undefined?p.localImage:`${c}/${id}.webp`),tags:Array.isArray(p.tags)?p.tags:(p.tags&&Array.isArray(p.tags.tr)?p.tags.tr:[]),icons:Array.isArray(p.icons)?p.icons:[],isAvailable:p.isAvailable!==false,isFeatured:!!p.isFeatured,isSignature:!!p.isSignature}}
function normalizeMenu(raw){if(!Array.isArray(raw))throw Error("menu.json dizi olmalı");return raw.map((c,i)=>({id:c.id||`category-${i+1}`,icon:c.icon||"fa-utensils",name:ensureLang(c.name||obj(c.id||`Kategori ${i+1}`)),desc:ensureLang(c.desc||obj("")),products:Array.isArray(c.products)?c.products.map((p,j)=>normalizeProduct(p,c.id||`category-${i+1}`,j)):[]}))}
async function loadCurrent(){if(location.protocol==="file:"){menu=normalizeMenu(JSON.parse(JSON.stringify(FALLBACK_MENU)));setStatus("File modunda gömülü hazır menü açıldı. Tam test için local server kullan.");activeCat=0;activeProduct=null;productSnapshot=null;renderAll();return}try{const r=await fetch("./menu.json?admin="+Date.now(),{cache:"no-cache"});if(!r.ok)throw Error(r.status);menu=normalizeMenu(await r.json());setStatus("Mevcut menu.json yüklendi.")}catch(e){menu=normalizeMenu(JSON.parse(JSON.stringify(FALLBACK_MENU)));setStatus("menu.json yüklenemedi; gömülü hazır menü açıldı.")}activeCat=0;activeProduct=null;productSnapshot=null;renderAll()}
function product(){return activeProduct?menu[activeProduct.cat]?.products?.[activeProduct.product]:null}
function categoryOfActive(){return activeProduct?menu[activeProduct.cat]:null}
function iconMeta(id){return ICON_OPTIONS.find(i=>i.id===id)||{id,emoji:"🏷️",label:String(id||"Etiket").replace("fa-",""),desc:"Tanımlı özel ikon"}}
function tagMeta(id){return TAG_OPTIONS[id]||{emoji:"🏷️",desc:"Ürün etiketi"}}
function badgeMetaValue(value){return BADGES.find(b=>b.value===value)||{emoji:"🏷️",label:value||"",desc:"Kart üstü satış vurgusu"}}
function isSameWord(a,b){return String(a||"").trim().toLocaleLowerCase("tr-TR")===String(b||"").trim().toLocaleLowerCase("tr-TR")}
function visibleSignature(p){return !!p.isSignature && !isSameWord(p.badge?.tr,"İmza")}
function visibleFeatured(p){return !!p.isFeatured && !isSameWord(p.badge?.tr,"Popüler") && !isSameWord(p.badge?.tr,"Çok satan")}
function renderAll(){renderMetrics();renderCats();renderCanvas();renderEditor();validate();renderChangesList()}
function renderMetrics(){const ps=menu.flatMap(c=>c.products||[]);$("metrics").innerHTML=[["Kategori",menu.length],["Ürün",ps.length],["Öne çıkan",ps.filter(p=>p.isFeatured).length],["Pasif",ps.filter(p=>!p.isAvailable).length]].map(x=>`<span class="metric">${x[1]} ${x[0]}</span>`).join("")}
function renderCats(){$("categoryList").innerHTML=menu.map((c,i)=>`<button class="catItem ${i===activeCat?"active":""}" data-cat="${i}"><span><b>${esc(c.name.tr||c.id)}</b><small>${c.products.length} ürün · ${c.id}</small></span><span>›</span></button>`).join("");document.querySelectorAll("[data-cat]").forEach(b=>b.onclick=()=>{activeCat=+b.dataset.cat;document.querySelector(`[data-section="${activeCat}"]`)?.scrollIntoView({behavior:"smooth"});renderCats()})}
function renderCanvas(){$("menuCanvas").innerHTML=menu.map((c,ci)=>`<section class="catSection" data-section="${ci}"><div class="catHeader"><input data-cat-name="${ci}" value="${esc(c.name.tr||c.id)}"><button data-add-product="${ci}">+ Ürün</button></div><div class="productGrid">${c.products.length?c.products.map((p,pi)=>cardHTML(p,ci,pi,true)).join(""):`<div class="emptyHint">Bu kategoride ürün yok.</div>`}</div></section>`).join("");bindCanvas()}
function cardHTML(p,ci,pi,editable=false){const rawImg=p.image||p.localImage||"";const img=esc(rawImg);return `<button class="menuCard ${activeProduct&&activeProduct.cat===ci&&activeProduct.product===pi?"active":""}" ${editable?`data-card="${ci}:${pi}" type="button"`:`type="button" tabindex="-1"`}><div class="menuCardImg ${rawImg?'':'placeholderArt'}">${rawImg?`<img src="${img}" onerror="this.parentElement.classList.add('placeholderArt');this.remove()">`:""}${editable?`<span class="editPill">Düzenle</span>`:""}</div><div class="menuCardBody"><div class="badgeLine">${p.badge?.tr?`<span class="badge">${badgeMetaValue(p.badge.tr).emoji} ${esc(p.badge.tr)}</span>`:""}${!p.isAvailable?`<span class="badge off">⛔ Pasif</span>`:""}${visibleFeatured(p)?`<span class="badge featured">⭐ Öne çıkan</span>`:""}${visibleSignature(p)?`<span class="badge signature">✍️ İmza</span>`:""}</div><div class="iconLine">${(p.icons||[]).map(i=>`<span class="miniIcon" title="${esc(iconMeta(i).label)}">${iconMeta(i).emoji}</span>`).join("")}</div><h3>${esc(p.name?.tr||p.id)}</h3><p>${esc(p.desc?.tr||"")}</p><div class="tagLine">${(p.tags||[]).slice(0,5).map(t=>`<span class="tagChip">${tagMeta(t).emoji} ${esc(t)}</span>`).join("")}</div><footer><span class="price">${Number(p.price)||0} ₺</span></footer></div></button>`}
function bindCanvas(){document.querySelectorAll("[data-card]").forEach(card=>card.onclick=()=>{const [cat,productIdx]=card.dataset.card.split(":").map(Number);activeProduct={cat,product:productIdx};productSnapshot=clone(menu[cat].products[productIdx]);renderAll();openSheet()});document.querySelectorAll("[data-cat-name]").forEach(input=>input.oninput=e=>{const old=menu[+e.target.dataset.catName].name.tr;menu[+e.target.dataset.catName].name.tr=e.target.value;renderCats();setStatus("Kategori adı taslakta değişti.")});document.querySelectorAll("[data-add-product]").forEach(b=>b.onclick=()=>openAddSheet("product",+b.dataset.addProduct))}
function openSheet(){$("editorSheet").classList.add("open");$("editorSheet").setAttribute("aria-hidden","false")}
function flash(area){if(!activeProduct)return;const card=document.querySelector(`[data-card="${activeProduct.cat}:${activeProduct.product}"]`);if(!card)return;card.classList.remove("flash-badge","flash-icons","flash-tags","flash-image","flash-text","flash-price");void card.offsetWidth;card.classList.add("flash-"+area);setTimeout(()=>card.classList.remove("flash-"+area),1200)}
function set(id,v){$(id).value=v??""}
function renderEditor(){const p=product(),open=!!p;$("editorBody").hidden=!open;$("editorEmpty").style.display=open?"none":"grid";if(!open)return;$("editorTitle").textContent=p.name.tr||p.id;set("ed_name_tr",p.name.tr);set("ed_desc_tr",p.desc.tr);set("ed_price",p.price);set("ed_badge_tr",p.badge.tr);set("ed_image",p.image);set("ed_localImage",p.localImage);const previewBox=$("ed_image_preview").parentElement;const previewSrc=p.image||p.localImage||"";previewBox.classList.toggle("placeholderArt",!previewSrc);$("ed_image_preview").style.display=previewSrc?"block":"none";$("ed_image_preview").src=previewSrc||"";$("ed_image_preview").onerror=()=>{previewBox.classList.add("placeholderArt");$("ed_image_preview").style.display="none"};set("ed_id",p.id);set("ed_name_en",p.name.en);set("ed_name_ru",p.name.ru);set("ed_name_ar",p.name.ar);set("ed_desc_en",p.desc.en);set("ed_desc_ru",p.desc.ru);set("ed_desc_ar",p.desc.ar);renderQuality();renderBadgeChoices();renderToggleChoices();renderPresetChoices();renderTagChoices();renderIconChoices()}
function bindField(id,fn,area){$(id).oninput=e=>{const p=product();if(!p)return;fn(p,e.target.value);renderCanvas();renderEditor();openSheet();flash(area);setStatus("Değişiklik taslak olarak işlendi.")}}
function renderQuality(){const p=product();let score=0,notes=[];function add(ok,label,points){if(ok){score+=points;notes.push(`<span class="good">✓ ${label}</span>`)}else notes.push(`<span class="missing">• Eksik: ${label}</span>`)}add(!!p.name.tr,"ürün adı",15);add(!!p.desc.tr,"açıklama",15);add(Number(p.price)>0,"fiyat",15);add(!!(p.image||p.localImage),"görsel",15);add(!!p.badge.tr,"rozet",10);add((p.tags||[]).length>0,"tag",10);add((p.icons||[]).length>0,"ikon",10);add(p.isAvailable!==false,"satışta",10);$("qualityScore").textContent=Math.min(score,100)+"/100";$("qualityFill").style.width=Math.min(score,100)+"%";$("qualityNotes").innerHTML=notes.slice(0,5).join("")}
function renderBadgeChoices(){$("badgePresets").innerHTML=BADGES.map(b=>`<button class="visualChoice ${product()?.badge?.tr===b.value?"active":""}" data-badge="${esc(b.value)}" type="button"><span class="symbol">${b.emoji}</span><span><b>${esc(b.label)}</b><span>${esc(b.desc)}</span></span></button>`).join("");document.querySelectorAll("[data-badge]").forEach(b=>b.onclick=()=>{product().badge.tr=b.dataset.badge;renderAll();openSheet();flash("badge")})}
function renderToggleChoices(){const p=product();[["toggleAvailable","isAvailable"],["toggleFeatured","isFeatured"],["toggleSignature","isSignature"]].forEach(([id,key])=>{$(id).classList.toggle("active",!!p[key]);$(id).onclick=()=>{p[key]=!p[key];renderAll();openSheet();flash("badge")}})}
function renderPresetChoices(){$("presetChoices").innerHTML=PRESETS.map(pr=>`<button class="presetChoice" data-preset="${pr.id}" type="button"><span class="symbol">${pr.emoji}</span><span><b>${pr.label}</b><span>${pr.desc}</span></span></button>`).join("");document.querySelectorAll("[data-preset]").forEach(b=>b.onclick=()=>applyPreset(b.dataset.preset))}
function applyPreset(id){const p=product(),pr=PRESETS.find(x=>x.id===id);if(!p||!pr)return;p.badge.tr=pr.badge;p.tags=[...new Set([...(p.tags||[]),...pr.tags])];p.icons=[...new Set([...(p.icons||[]),...pr.icons])];if(pr.signature)p.isSignature=true;if(pr.featured)p.isFeatured=true;renderAll();openSheet();flash("icons");setStatus(`${pr.label} uygulandı.`)}
function renderTagChoices(){const p=product();const base=new Set(TAG_GROUPS.flatMap(g=>g.items));const custom=(p.tags||[]).filter(t=>!base.has(t));const groups=[...TAG_GROUPS];if(custom.length)groups.push({title:"Bu üründeki özel tagler",items:custom});$("tagChoices").innerHTML=groups.map(g=>`<div class="choiceGroup"><h4>${g.title}</h4><div class="choiceWrap">${g.items.map(t=>{const meta=tagMeta(t);return `<button class="visualChoice tagChoice ${(p.tags||[]).includes(t)?"active":""}" data-tag="${esc(t)}" type="button"><span class="symbol">${meta.emoji}</span><span><b>${esc(t)}</b><span>${esc(meta.desc)}</span></span></button>`}).join("")}</div></div>`).join("");document.querySelectorAll("[data-tag]").forEach(b=>b.onclick=()=>toggleArray("tags",b.dataset.tag,"tags"))}
function renderIconChoices(){$("iconChoices").innerHTML=ICON_OPTIONS.map(i=>`<button class="visualChoice ${(product().icons||[]).includes(i.id)?"active":""}" data-icon="${i.id}" type="button"><span class="symbol">${i.emoji}</span><span><b>${i.label}</b><span>${i.desc}</span></span></button>`).join("");document.querySelectorAll("[data-icon]").forEach(b=>b.onclick=()=>toggleArray("icons",b.dataset.icon,"icons"))}
function toggleArray(key,val,area){const p=product();p[key]=Array.isArray(p[key])?p[key]:[];p[key].includes(val)?p[key]=p[key].filter(x=>x!==val):p[key].push(val);renderAll();openSheet();flash(area)}
function templateProduct(type,id,name,catId){const base={id,name:obj(name||"Yeni Ürün"),price:0,isAvailable:true,image:"",localImage:""};if(type==="coffee")return normalizeProduct({...base,price:150,desc:obj("Kahve bazlı özel içecek."),badge:obj("Yeni"),tags:["kahve yanı","popüler"],icons:["fa-mug-hot","fa-star"]},catId,0);if(type==="dessert")return normalizeProduct({...base,price:190,desc:obj("Kahve yanında önerilen tatlı."),badge:obj("Şefin önerisi"),tags:["tatlı","kahve yanı"],icons:["fa-cookie-bite","fa-mug-hot"]},catId,0);if(type==="starter")return normalizeProduct({...base,price:175,desc:obj("Paylaşmaya uygun başlangıç."),badge:obj("Yeni"),tags:["paylaşmalık","taze"],icons:["fa-people-group","fa-leaf"]},catId,0);return normalizeProduct(base,catId,0)}
function addProduct(ci=activeCat,type="blank",name="Yeni Ürün"){const c=menu[ci];if(!c)return;const id=`${c.id}-${slug(name)}-${Date.now().toString().slice(-4)}`;c.products.push(templateProduct(type,id,name,c.id));activeCat=ci;activeProduct={cat:ci,product:c.products.length-1};productSnapshot=clone(c.products[c.products.length-1]);logChange("Ürün eklendi",`${name} · ${c.name.tr||c.id}`);saveDraftSilent();renderAll();openSheet()}
function duplicateProduct(){const p=product();if(!p)return;const c=menu[activeProduct.cat],copy=clone(p);copy.id=slug(copy.id+"-copy");copy.name.tr=(copy.name.tr||copy.id)+" Kopya";c.products.splice(activeProduct.product+1,0,copy);activeProduct={cat:activeProduct.cat,product:activeProduct.product+1};productSnapshot=clone(copy);logChange("Ürün kopyalandı",`${copy.name.tr} · ${c.name.tr||c.id}`);saveDraftSilent();renderAll();openSheet()}
function deleteProduct(){const p=product();if(!activeProduct||!p||!confirm("Ürünü silmek istiyor musun?"))return;const c=menu[activeProduct.cat];c.products.splice(activeProduct.product,1);logChange("Ürün silindi",`${p.name.tr||p.id} · ${c.name.tr||c.id}`);activeProduct=null;productSnapshot=null;saveDraftSilent();renderAll();$("editorSheet").classList.remove("open")}
function addCategory(name="Yeni Kategori",id=""){const finalId=slug(id||name||`category-${Date.now().toString().slice(-4)}`);menu.push({id:finalId,icon:"fa-utensils",name:obj(name||"Yeni Kategori"),desc:obj(""),products:[]});activeCat=menu.length-1;logChange("Kategori eklendi",`${name} · ${finalId}`);saveDraftSilent();renderAll()}
function refreshCategorySelect(){const sel=$("newProductCategory");if(!sel)return;sel.innerHTML=menu.map((c,i)=>`<option value="${i}" ${i===activeCat?"selected":""}>${esc(c.name.tr||c.id)}</option>`).join("")}
function templateLabel(type){return {blank:"Boş ürün",coffee:"Kahve ürünü",dessert:"Tatlı ürünü",starter:"Başlangıç / atıştırmalık"}[type]||"Boş ürün"}
function updateAddProductSummary(){const ci=Number($("newProductCategory").value||activeCat);const cat=menu[ci];const name=$("newProductName").value.trim()||"Yeni Ürün";const type=$("newProductTemplate").value||"blank";$("addSummaryName").textContent=name;$("addSummaryCategory").textContent=cat?`Kategori: ${cat.name.tr||cat.id}`:"Kategori seçilmedi";$("addSummaryTemplate").textContent=`Şablon: ${templateLabel(type)}`}
function updateAddCategorySummary(){const name=$("newCategoryName").value.trim()||"Yeni Kategori";const id=slug($("newCategoryId").value.trim()||name);$("addCategorySummaryName").textContent=name;$("addCategorySummaryId").textContent=id}
function openAddSheet(mode="product",ci=activeCat){activeCat=ci;refreshCategorySelect();$("addSheet").classList.add("open");$("addSheet").setAttribute("aria-hidden","false");const isCategory=mode==="category";$("addSheetTitle").textContent=isCategory?"Kategori ekle":"Ürün ekle";$("addSheetEyebrow").textContent=isCategory?"Yeni kategori":"Yeni ürün";$("addProductPanel").hidden=isCategory;$("addCategoryPanel").hidden=!isCategory;if(!isCategory){$("newProductName").value="";$("newProductTemplate").value="blank";$("newProductCategory").value=String(activeCat);updateAddProductSummary();setTimeout(()=>$("newProductName").focus(),60)}else{$("newCategoryName").value="";$("newCategoryId").value="";updateAddCategorySummary();setTimeout(()=>$("newCategoryName").focus(),60)}}
function closeAddSheet(){if(document.activeElement&&$("addSheet").contains(document.activeElement))document.activeElement.blur();$("addSheet").classList.remove("open");$("addSheet").setAttribute("aria-hidden","true")}
function confirmAddProduct(){if(document.activeElement)document.activeElement.blur();const ci=Number($("newProductCategory").value||activeCat);const name=$("newProductName").value.trim()||"Yeni Ürün";const type=$("newProductTemplate").value||"blank";closeAddSheet();addProduct(ci,type,name);setStatus(`${name} eklendi.`)}
function confirmAddCategory(){const name=$("newCategoryName").value.trim()||"Yeni Kategori";const id=$("newCategoryId").value.trim();closeAddSheet();addCategory(name,id);setStatus(`${name} kategorisi eklendi.`)}
function diffProducts(before,after){const changes=[];if(!before||!after)return changes;const pairs=[["name.tr","Ürün adı"],["desc.tr","Açıklama"],["price","Fiyat"],["badge.tr","Rozet"],["image","İnternet görseli"],["localImage","Yerel görsel"],["isAvailable","Satışta"],["isFeatured","Öne çıkan"],["isSignature","İmza ürün"]];function get(o,path){return path.split(".").reduce((a,k)=>a?.[k],o)}function fmt(v){if(Array.isArray(v))return v.join(", ")||"—";if(typeof v==="boolean")return v?"Evet":"Hayır";return String(v??"—")}pairs.forEach(([path,label])=>{const a=get(before,path),b=get(after,path);if(JSON.stringify(a)!==JSON.stringify(b))changes.push({label,before:fmt(a),after:fmt(b)})});[["tags","Tagler"],["icons","İkonlar"]].forEach(([key,label])=>{if(JSON.stringify(before[key]||[])!==JSON.stringify(after[key]||[]))changes.push({label,before:fmt(before[key]||[]),after:fmt(after[key]||[])})});return changes}
function openReview(){const p=product();if(!p)return;const changes=diffProducts(productSnapshot||{},p);pendingReviewChanges=changes;$("reviewTitle").textContent=`${p.name.tr||p.id} güncellenecek`;$("reviewChangeList").innerHTML=changes.length?changes.map(c=>`<div class="reviewDiff"><b>${esc(c.label)}</b><span>Eski: ${esc(c.before)}</span><span>Yeni: ${esc(c.after)}</span></div>`).join(""):`<div class="ok">Bu üründe yeni değişiklik yok. Yine de taslağı kaydedebilirsin.</div>`;$("reviewCardMount").innerHTML=cardHTML(p,activeProduct.cat,activeProduct.product,false);$("reviewModal").classList.add("open");$("reviewModal").setAttribute("aria-hidden","false")}
function closeReview(){if(document.activeElement&&$("reviewModal").contains(document.activeElement))document.activeElement.blur();$("reviewModal").classList.remove("open");$("reviewModal").setAttribute("aria-hidden","true")}
function confirmReview(){if(document.activeElement)document.activeElement.blur();const p=product();if(!p)return;saveDraftSilent();logChange("Ürün güncellendi",`${p.name.tr||p.id} · ${(categoryOfActive()?.name.tr)||""}`,pendingReviewChanges);productSnapshot=clone(p);closeReview();setStatus("Değişiklikler onaylandı ve taslak kaydedildi.");const sheet=$("editorSheet");sheet.classList.remove("savePulse");void sheet.offsetWidth;sheet.classList.add("savePulse");renderChangesList()}
function revertReview(){if(activeProduct&&productSnapshot){menu[activeProduct.cat].products[activeProduct.product]=clone(productSnapshot);closeReview();renderAll();openSheet();setStatus("Değişiklikler geri alındı.")}}
function saveDraftSilent(){localStorage.setItem(PREVIEW_MENU_KEY,JSON.stringify(menu))}
function loadLog(){try{return JSON.parse(localStorage.getItem(LOG_KEY)||"[]")}catch{return[]}}
function saveLog(items){localStorage.setItem(LOG_KEY,JSON.stringify(items.slice(0,80)))}
function logChange(title,detail,changes=[]){const items=loadLog();items.unshift({time:new Date().toLocaleString("tr-TR"),title,detail,changes});saveLog(items);renderChangesList()}
function renderChangesList(){const items=loadLog();const el=$("changesList");if(el)el.innerHTML=items.length?items.map(item=>`<article class="logItem"><small>${esc(item.time)}</small><b>${esc(item.title)}</b><span>${esc(item.detail||"")}</span>${item.changes?.length?`<span>${item.changes.length} alan değişti</span>`:""}</article>`).join(""):`<div class="ok">Henüz kayıt yok.</div>`;const mini=$("recentChangesMini");if(mini)mini.innerHTML=items.length?items.slice(0,4).map(item=>`<article class="miniLogItem"><b>${esc(item.title)}</b><span>${esc(item.detail||"")}</span><span>${esc(item.time)}</span></article>`).join(""):`<div class="ok">Henüz kayıt yok.</div>`}
function openChanges(){$("changesDrawer").classList.add("open");$("changesDrawer").setAttribute("aria-hidden","false");renderChangesList()}
function closeChanges(){$("changesDrawer").classList.remove("open");$("changesDrawer").setAttribute("aria-hidden","true")}
function clearLog(){if(confirm("Değişiklik logu temizlensin mi?")){saveLog([]);renderChangesList();setStatus("Değişiklik logu temizlendi.")}}
function validate(){const ids=new Set(),w=[];menu.forEach(c=>(c.products||[]).forEach(p=>{if(ids.has(p.id))w.push("Tekrarlanan ID: "+p.id);ids.add(p.id);if(!p.name?.tr)w.push("TR ad eksik: "+p.id)}));$("validation").innerHTML=w.length?w.map(x=>`<div class="warn">${x}</div>`).join(""):`<div class="ok">JSON geçerli görünüyor.</div>`}
function download(){saveDraftSilent();const blob=new Blob([JSON.stringify(menu,null,2)+"\n"],{type:"application/json"});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="menu.json";a.click();URL.revokeObjectURL(a.href)}
function preview(){saveDraftSilent();window.open("./index.html?mode=demo&preview=local","_blank")}
bindField("ed_name_tr",(p,v)=>p.name.tr=v,"text");bindField("ed_desc_tr",(p,v)=>{p.desc.tr=v;p.detail.tr=v},"text");bindField("ed_price",(p,v)=>p.price=Number(v)||0,"price");bindField("ed_badge_tr",(p,v)=>p.badge.tr=v,"badge");bindField("ed_image",(p,v)=>p.image=v,"image");bindField("ed_localImage",(p,v)=>p.localImage=v,"image");bindField("ed_id",(p,v)=>p.id=slug(v),"text");bindField("ed_name_en",(p,v)=>p.name.en=v,"text");bindField("ed_name_ru",(p,v)=>p.name.ru=v,"text");bindField("ed_name_ar",(p,v)=>p.name.ar=v,"text");bindField("ed_desc_en",(p,v)=>p.desc.en=v,"text");bindField("ed_desc_ru",(p,v)=>p.desc.ru=v,"text");bindField("ed_desc_ar",(p,v)=>p.desc.ar=v,"text");
$("closeEditorBtn").onclick=()=>$("editorSheet").classList.remove("open");$("saveDraftBtn").onclick=openReview;$("duplicateBtn").onclick=duplicateProduct;$("deleteBtn").onclick=deleteProduct;$("loadCurrentBtn").onclick=loadCurrent;$("fileInput").onchange=async e=>{const f=e.target.files[0];if(!f)return;menu=normalizeMenu(JSON.parse(await f.text()));activeProduct=null;productSnapshot=null;renderAll();setStatus("JSON içe aktarıldı.")};$("downloadBtn").onclick=download;$("previewBtn").onclick=preview;$("addProductBtn").onclick=()=>openAddSheet("product",activeCat);$("openAddCategoryBtn").onclick=()=>openAddSheet("category");$("closeAddSheetBtn").onclick=closeAddSheet;$("cancelAddProductBtn").onclick=closeAddSheet;$("cancelAddCategoryBtn").onclick=closeAddSheet;$("confirmAddProductBtn").onclick=confirmAddProduct;$("confirmAddCategoryBtn").onclick=confirmAddCategory;$("newProductCategory").onchange=updateAddProductSummary;$("newProductTemplate").onchange=updateAddProductSummary;$("newProductName").oninput=updateAddProductSummary;$("newCategoryName").oninput=updateAddCategorySummary;$("newCategoryId").oninput=updateAddCategorySummary;$("addSheet").onclick=e=>{if(e.target.id==="addSheet")closeAddSheet()};$("openChangesBtn").onclick=openChanges;$("openChangesMiniBtn").onclick=openChanges;$("closeChangesBtn").onclick=closeChanges;$("drawerPreviewBtn").onclick=preview;$("drawerDownloadBtn").onclick=download;$("clearLogBtn").onclick=clearLog;$("closeReviewBtn").onclick=closeReview;$("confirmReviewBtn").onclick=confirmReview;$("revertReviewBtn").onclick=revertReview;$("reviewModal").onclick=e=>{if(e.target.id==="reviewModal")closeReview()};loadCurrent();
